-- Vashj'ir: combat and quest scripts of creatures that had none. The creatures had no AIName, so they only stood and
-- were hit. The rows are the 4.3.4 combat spells where that data has them, and the 5.4.8 rows otherwise. Erunak Stonespeaker
-- (41618) also gives the credit 36901 of "Call of Duty" when a player reaches him: no data set has another source for it.

DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (36915, 39389, 39397, 39422, 39662, 39663, 40162, 40237, 40238, 40239, 40372, 40710, 40737, 40759, 40770, 40782, 40831, 40878, 41102, 41105, 41106, 41107, 41108, 41235, 41249, 41250, 41256, 41451, 41537, 41579, 41618, 41672, 41780, 41781, 41784, 41805, 41808, 41896, 41994, 41995, 41996, 42058, 42060, 42061, 42062, 42063, 42069, 42818, 42819, 43177, 46468, 47397, 49913, 50009, 50050, 50051);
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (36915, 39389, 39397, 39422, 39662, 39663, 40162, 40237, 40238, 40239, 40372, 40710, 40737, 40759, 40770, 40782, 40831, 40878, 41102, 41105, 41106, 41107, 41108, 41235, 41249, 41250, 41256, 41451, 41537, 41579, 41618, 41672, 41780, 41781, 41784, 41805, 41808, 41896, 41994, 41995, 41996, 42058, 42060, 42061, 42062, 42063, 42069, 42818, 42819, 43177, 46468, 47397, 49913, 50009, 50050, 50051) AND `AIName` = '';
